<?php require __DIR__.'/_layout.php';$u=require_admin();$pdo=db();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$act=$_POST['action']??'save';if($act==='delete'){$id=(int)$_POST['id'];$st=$pdo->prepare("SELECT image_path FROM achievements WHERE id=?");$st->execute([$id]);$old=(string)$st->fetchColumn();$pdo->prepare("DELETE FROM achievements WHERE id=?")->execute([$id]);delete_local_media($old);go('conquistas.php','Conquista removida.');}$img='';if(!empty($_FILES['image']['name']))$img=upload_file($_FILES['image'],'image');$pdo->prepare("INSERT INTO achievements(year,title,competition,result,description,image_path,sort_order,published) VALUES(?,?,?,?,?,?,?,?)")->execute([trim($_POST['year']??''),trim($_POST['title']??''),trim($_POST['competition']??''),trim($_POST['result']??''),trim($_POST['description']??''),$img,(int)($_POST['sort_order']??100),isset($_POST['published'])?1:0]);go('conquistas.php','Conquista cadastrada.');}catch(Throwable $e){$err=$e->getMessage();}}$rows=$pdo->query("SELECT * FROM achievements ORDER BY sort_order,id DESC")->fetchAll();admin_header('Conquistas e Campeonatos');$msg=flash();?>
<?php if($msg):?><div class="alert ok"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?>
<form class="panel form-stack" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><h2>Nova conquista</h2><div class="grid2"><label>Ano<input name="year"></label><label>Título<input name="title" required placeholder="Ex.: Campeã Estadual"></label><label>Campeonato / evento<input name="competition"></label><label>Resultado / colocação<input name="result"></label></div><label>Descrição<textarea name="description"></textarea></label><div class="grid2"><label>Foto<input type="file" name="image" accept="image/*"></label><label>Ordem<input type="number" name="sort_order" value="100"></label></div><label class="check"><input type="checkbox" name="published" checked> Publicar</label><button class="primary">CADASTRAR</button></form>
<div class="records"><?php foreach($rows as $r):?><article><?php if($r['image_path']):?><img src="../<?=e($r['image_path'])?>" alt=""><?php endif;?><div><span><?=e($r['year'])?></span><h3><?=e($r['title'])?></h3><strong><?=e($r['result'])?></strong><p><?=e($r['competition'])?> · <?=e($r['description'])?></p></div><form method="post" onsubmit="return confirm('Remover esta conquista?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger">Excluir</button></form></article><?php endforeach;?></div>
<?php admin_footer();?>
